/* assets/account-progress.js */
/* Shared private progress row. Compare-and-swap prevents unrelated page saves
   from replacing one another. Uses the existing tesselate_progress RLS policies. */
(() => {
 'use strict';
 const table='tesselate_progress';
 const fail=e=>{if(e)throw new Error(e.message||'Account storage is unavailable.');};
 async function read(client,owner){
  const {data,error}=await client.from(table).select('progress_json,updated_at').eq('user_id',owner).maybeSingle();
  fail(error);return data;
 }
 window.TesselateProgress={read,
  async mutate(client,owner,transform,isCurrent=()=>true){
   for(let attempt=0;attempt<8;attempt++){
    if(!isCurrent())throw new Error('Account changed. Your draft is kept on this device.');
    const row=await read(client,owner);
    if(!isCurrent())throw new Error('Account changed. Your draft is kept on this device.');
    const progress=transform(structuredClone(row?.progress_json||{}));
    const updated_at=new Date(Math.max(Date.now(),Date.parse(row?.updated_at||0)+1||0)).toISOString();
    let result;
    if(row)result=await client.from(table).update({progress_json:progress,updated_at}).eq('user_id',owner).eq('updated_at',row.updated_at).select('user_id');
    else result=await client.from(table).upsert({user_id:owner,progress_json:progress,updated_at},{onConflict:'user_id',ignoreDuplicates:true}).select('user_id');
    fail(result.error);
    if(result.data?.length)return progress;
   }
   throw new Error('Another page is saving. Retry to save your draft.');
  }
 };
})();

;
/* phys210/lab4-account.js */
/* Lab drafts are scoped to an authenticated owner; guest drafts require an
   explicit import. Pending field patches survive reloads and offline failures. */
(() => {
 'use strict';
 const NS='__phys210_lab4',BASE='phys210-lab4-account-v1:',GUEST='phys210-lab4-bench-v1';
 let client,subscription,owner=null,epoch=0,timer,ready=false;
 function bounded(promise){let timeout;return Promise.race([promise,new Promise((_,reject)=>{timeout=setTimeout(()=>reject(new Error("Account connection timed out.")),8000);})]).finally(()=>clearTimeout(timeout));}
 const inFlight=new Set();
 let pending={},draft={},step=0;
 const label=document.getElementById('accountStatus'),status=document.getElementById('saveStatus');
 const retry=document.getElementById('retryAccount'),adopt=document.getElementById('adoptLocal');
 const hasData=o=>Object.values(o||{}).some(v=>v!==''&&v!==false&&v!==null);
 const guestReadings=()=>get(BASE+'guest')?.draft||get(GUEST)||{};
 const get=k=>{try{return JSON.parse(localStorage.getItem(k)||'null');}catch{return null;}};
 function persist(){try{localStorage.setItem(BASE+(owner||'guest'),JSON.stringify({draft,pending,step}));return true;}catch{status.textContent='Device storage unavailable. Download a readings backup; retry the account save.';return false;}}
 function message(text){status.textContent=text;}
 function lock(value){document.querySelectorAll('[data-key]').forEach(el=>el.disabled=value);document.getElementById('load').disabled=value;}
 function apply(data){draft=Lab4UI.clean(data||{});Lab4UI.apply(draft,step);}
 function schedule(){clearTimeout(timer);if(owner&&ready){message('Saved on this device · saving to your account…');timer=setTimeout(flush,900);}else message('Saved on this device · sign in to sync across devices.');}
 async function flush(){
  if(!owner||!ready||inFlight.has(epoch))return;
  const who=owner,token=epoch,patch=structuredClone(pending);
  if(!Object.keys(patch).length){message('Saved to your account.');return;}
  inFlight.add(token);message('Saving to your account…');
  try{
   const saved=await TesselateProgress.mutate(client,who,all=>{
    const old=all[NS]||{};
    all[NS]={version:1,readings:{...Lab4UI.clean(old.readings||{}),...(patch.readings||{})},step:patch.step??old.step??0};return all;
   },()=>owner===who&&epoch===token);
   if(owner!==who||epoch!==token)return;
   // Clear only values that were actually saved; retain edits made in flight.
   for(const [k,v] of Object.entries(patch.readings||{}))if(pending.readings?.[k]===v)delete pending.readings[k];
   if(pending.readings&&!Object.keys(pending.readings).length)delete pending.readings;
   if(pending.step===patch.step)delete pending.step;
   const remaining=Object.keys(pending).length;
   apply({...saved[NS].readings,...(pending.readings||{})});persist();
   message(remaining?'Saved on this device · more changes waiting to sync.':'Saved to your account.');
  }catch(e){if(owner===who&&epoch===token)message('Account save pending · '+e.message+' Use Retry sync or save a backup.');}
  finally{inFlight.delete(token);if(owner===who&&epoch===token&&Object.keys(pending).length&&status.textContent.startsWith('Saved on this device'))schedule();}
 }
 async function activate(user,force=false){
  const next=user?.id||null;if(!force&&ready&&next===owner)return;
  epoch++;const token=epoch;clearTimeout(timer);ready=true;owner=next;lock(false);
  label.textContent=user?'Signed in as '+(user.email||'your account'):'Not signed in';
  retry.hidden=!user;adopt.hidden=!user||!hasData(guestReadings());
  const local=get(BASE+(owner||'guest'))||{};
  draft=local.draft||{};pending=local.pending||{};step=local.step||0;
  if(pending.readings){const normalized=Lab4UI.clean({...draft,...pending.readings});for(const key of Object.keys(pending.readings))pending.readings[key]=normalized[key];if(normalized.capacitanceUnit)pending.readings.capacitanceUnit=normalized.capacitanceUnit;}
  if(!owner){apply(local.draft||get(GUEST)||{});ready=true;lock(false);message('Saved on this device · sign in through the course workspace to sync.');return;}
  apply(draft);message('Checking account for saved readings… You can enter measurements now.');
  try{
   const row=await bounded(TesselateProgress.read(client,owner));
   if(token!==epoch)return;
   const saved=row?.progress_json?.[NS]||{};
   step=pending.step??saved.step??step;
   const merged={...Lab4UI.clean(saved.readings||{}),...(pending.readings||{})};
   const earlier=row?.progress_json?.__phys210_lab7?.readings||{};
   for(const key of ['student','section'])if(!merged[key]?.trim()&&earlier[key]?.trim())merged[key]=earlier[key];
   apply(merged);
   // Save newly prepared writing without replacing existing measurements or edits.
   for(const [key,value] of Object.entries(draft))if(value!==''&&value!==(saved.readings||{})[key])pending.readings={...(pending.readings||{}),[key]:value};
   persist();
   ready=true;lock(false);
   if(Object.keys(pending).length)await flush();else message('Account progress loaded · changes save automatically.');
  }catch(e){if(token===epoch){ready=true;lock(false);message('Could not load account progress · '+e.message+' Local edits will be kept until Retry sync succeeds.');}}
 }
 window.Lab4Account={
  capture(values,currentStep){
   if(!ready)return;
   const clean=Lab4UI.clean(values);
   const changes={};for(const [k,v] of Object.entries(clean))if(draft[k]!==v)changes[k]=v;
   if(Object.keys(changes).length)pending.readings={...(pending.readings||{}),...changes};
   if(currentStep!==step)pending.step=currentStep;
   draft=clean;step=currentStep;persist();schedule();
  }
 };
 retry.onclick=async()=>{if(!ready)return;try{if(!client){await init();return;}const {data,error}=await bounded(client.auth.getSession());if(error)throw error;await activate(data.session?.user||null,true);}catch(e){message(e.message+' Your entries are kept on this device. Try Retry sync again.');}};
 adopt.onclick=()=>{
  if(!ready||!owner)return;
  if(!confirm('Copy this device’s earlier local Experiment 4 readings into the signed-in account? Matching fields will replace that account’s readings.'))return;
  const imported=Lab4UI.clean(guestReadings());
  const merged={...draft,...imported};Lab4Account.capture(merged,step);apply(merged);
 };
 window.addEventListener('online',()=>flush());
 document.addEventListener('visibilitychange',()=>{if(document.hidden)flush();});
 window.addEventListener('beforeunload',e=>{if(owner&&Object.keys(pending).length){e.preventDefault();e.returnValue='';}});
 async function init(){
  await activate(null,true);
  try{
   if(!window.supabase||!window.TesselateProgress)throw new Error('Sign-in could not load. Reload when connected.');
   client=client||window.supabase.createClient('https://xsscvdooviztaxzuwbmr.supabase.co','sb_publishable_BTkvBDZodnIPQoJ4nFEhMQ_Wd5me5QY');
   const {data,error}=await bounded(client.auth.getSession());if(error)throw error;
   await activate(data.session?.user||null);
  }catch(e){await activate(null,true);label.textContent='Account connection unavailable';retry.hidden=false;message(e.message+' You can enter measurements now; they are saved on this device.');}
  finally{
   // Defer work outside the Supabase auth callback lock, including late recovery.
   if(client&&!subscription){subscription=true;client.auth.onAuthStateChange((_event,session)=>setTimeout(()=>activate(session?.user||null),0));}
  }
 }
 init();
})();

